<script setup lang="ts">
import { useDocumentMetadata } from '@/composables/useDocumentMetadata';
import { onMounted, ref, watch, nextTick, computed, toRaw } from 'vue';
import type { ObjectDirective } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { onKeyStroke } from '@vueuse/core';
import draggable from 'vuedraggable';
import { useSettings } from '@/composables/useSettings';
import { defineAsyncComponentAndLoadOnMounted } from '@/utils/vue';
// IMPORTANT: Branding is part of the initial sidebar layout and must not flicker.
import SidebarHeader from './SidebarHeader.vue';
// IMPORTANT: ModelSelector is part of the initial sidebar layout and should not flicker.
import ModelSelector from './ModelSelector.vue';
import PWAUpdateNotification from './PWAUpdateNotification.vue';
const SidebarDebugControls = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./SidebarDebugControls.vue') });
import type { ChatGroup, SidebarItem, ChatSidebarItem } from '@/01-models/types';
import {
  Trash2Icon, SettingsIcon,
  PencilIcon, FolderIcon, FolderPlusIcon,
  ChevronDownIcon, ChevronUpIcon, ChevronRightIcon, CheckIcon, XIcon,
  BotIcon, SquarePenIcon, Loader2Icon, MoreHorizontalIcon,
  SearchIcon, GhostIcon, MessageSquarePlusIcon,
} from 'lucide-vue-next';
import { idToRaw } from '@/01-models/ids';
import type { ChatGroupId, ChatId } from '@/01-models/ids';

const ChatGroupActions = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./ChatGroupActions.vue') });
import { useLayout } from '@/composables/useLayout';
import { useConfirm } from '@/composables/useConfirm';
import { useGlobalSearch } from '@/features/global-search/composables/useGlobalSearch';
import { useEventTargetListener } from '@/composables/useEventTargetListener';
import { naturalSort } from '@/utils/string';
import { scrollIntoViewSafe } from '@/utils/dom';
import { isChatProcessing } from '@/composables/chat/chat-activity-queries';
import { useChatMetadata } from '@/composables/chat/useChatMetadata';
import { useCurrentChatState } from '@/composables/chat/ui/useCurrentChatState';
import { useChatLifecycle } from '@/composables/chat/ui/useChatLifecycle';
import { useChatNavigation } from '@/composables/chat/ui/useChatNavigation';
import { useChatOrganization } from '@/composables/chat/ui/useChatOrganization';
import { useSidebarStructure } from '@/composables/chat/ui/useSidebarStructure';
import { ensureStrings, lazyStrings } from '@/strings';

const currentChatState = useCurrentChatState();
const documentMetadata = useDocumentMetadata();
const chatLifecycle = useChatLifecycle();
const chatNavigation = useChatNavigation();
const chatOrganization = useChatOrganization();
const chatMetadata = useChatMetadata();
const sidebarStructure = useSidebarStructure();
const currentChat = currentChatState.currentChat;
const currentChatGroup = currentChatState.currentChatGroup;
const sidebarItems = currentChatState.sidebarItems;
const chatGroups = currentChatState.chatGroups;

function isProcessing({
  chatId,
}: {
  chatId: ChatId,
}) {
  return isChatProcessing({ chatId });
}

const persistSidebarStructure = sidebarStructure.persistSidebarStructure;

function setChatGroupCollapsed({
  groupId,
  isCollapsed,
}: {
  groupId: ChatGroupId,
  isCollapsed: boolean,
}) {
  void sidebarStructure.setChatGroupCollapsed({
    groupId,
    isCollapsed,
  });
}

function createChatGroup({
  name,
}: {
  name: string,
}) {
  return chatOrganization.createChatGroup({
    name,
    options: undefined,
  });
}

function deleteChatGroup({
  id,
}: {
  id: ChatGroupId,
}) {
  return chatOrganization.deleteChatGroup({
    id,
  });
}

function createNewChat({
  groupId,
  modelId,
  systemPrompt,
}: {
  groupId: ChatGroupId | undefined,
  modelId: string | undefined,
  systemPrompt: ChatGroup['systemPrompt'],
}) {
  return chatLifecycle.createNewChat({
    groupId,
    modelId,
    systemPrompt,
  });
}

function openChat({
  id,
}: {
  id: ChatId,
}) {
  return chatNavigation.openChat({
    chatId: id,
    leafId: undefined,
  });
}

function openChatGroup({
  id,
}: {
  id: ChatGroupId,
}) {
  chatNavigation.openChatGroup({
    groupId: id,
  });
}

function deleteChat({
  id,
}: {
  id: ChatId,
}) {
  return chatLifecycle.deleteChat({
    id,
    injectAddToast: undefined,
  });
}

function renameChat({
  id,
  newTitle,
}: {
  id: ChatId,
  newTitle: string,
}) {
  return chatMetadata.rename({
    chatId: id,
    title: newTitle,
  });
}

const renameChatGroup = chatOrganization.renameChatGroup;
const duplicateChatGroup = chatOrganization.duplicateChatGroup;

const { settings, isFetchingModels, availableModels, updateGlobalModel } = useSettings();
const sortedModels = computed(() => naturalSort({ values: availableModels.value || [] }));
const layout = useLayout();
const { isSidebarOpen, activeFocusArea, setActiveFocusArea, toggleSidebar } = layout;
const activeFocusAreaVersion = 'activeFocusAreaVersion' in layout ? layout.activeFocusAreaVersion : ref(0);
const { showConfirm } = useConfirm();

const router = useRouter();
const route = useRoute();

defineEmits<{
  (e: 'open-settings'): void,
}>();

const sidebarItemsLocal = ref<SidebarItem[]>([]);
const isDragging = ref(false);
const dragHoverGroup = ref<ChatGroupId | null>(null);
let dragHoverTimeout: ReturnType<typeof setTimeout> | null = null;
let isInternalUpdate = false;

const editingId = ref<ChatId | null>(null);
const editingTitle = ref('');
const isCreatingChatGroup = ref(false);
const newChatGroupName = ref('');
const editingChatGroupId = ref<ChatGroupId | null>(null);
const editingChatGroupName = ref('');
const skipLeaveAnimation = ref(false);
const lastNavigatedId = ref<string | null>(null);

const activeActionGroupId = ref<ChatGroupId | null>(null);

const COMPACT_THRESHOLD = 5;
const expandedGroupIds = ref<Set<ChatGroupId>>(new Set());
const collapsingGroupIds = ref<Set<ChatGroupId>>(new Set());

const navContainer = ref<HTMLElement | null>(null);

const visibleItems = computed(() => {
  const result: (
    | { type: 'chat', id: ChatId }
    | { type: 'chat_group', id: ChatGroupId }
    | { type: 'expand_button', id: string, groupId: ChatGroupId }
  )[] = [];
  function collect({ list }: { list: SidebarItem[] }) {
    for (const item of list) {
      switch (item.type) {
      case 'chat':
        result.push({ type: 'chat', id: item.chat.id });
        break;
      case 'chat_group':
        result.push({ type: 'chat_group', id: item.chatGroup.id });
        if (!item.chatGroup.isCollapsed) {
          const items = item.chatGroup.items;
          const isExpanded = isGroupCompactExpanded({ groupId: item.chatGroup.id });
          const shownItems = (isExpanded || items.length <= COMPACT_THRESHOLD)
            ? items
            : items.slice(0, COMPACT_THRESHOLD);

          collect({ list: shownItems });

          if (items.length > COMPACT_THRESHOLD) {
            result.push({
              type: 'expand_button',
              id: `expand-${idToRaw({ id: item.chatGroup.id })}`,
              groupId: item.chatGroup.id,
            });
          }
        }
        break;
      default: {
        const _ex: never = item;
        return _ex;
      }
      }
    }
  }
  collect({ list: sidebarItemsLocal.value });
  return result;
});

const focusedId = computed(() => {
  if (lastNavigatedId.value && visibleItems.value.some(i => {
    switch (i.type) {
    case 'expand_button':
      return i.id === lastNavigatedId.value;
    case 'chat':
    case 'chat_group':
      return idToRaw({ id: i.id }) === lastNavigatedId.value;
    default: {
      const _ex: never = i;
      throw new Error(`Unhandled item type: ${((_ex satisfies never) as { readonly type: string }).type}`);
    }
    }
  })) {
    return lastNavigatedId.value;
  }
  return currentChatGroup.value ? idToRaw({ id: currentChatGroup.value.id }) : currentChat.value ? idToRaw({ id: currentChat.value.id }) : null;
});

function isSidebarItemVisible({
  container,
  element,
}: {
  container: HTMLElement,
  element: HTMLElement,
}) {
  const containerRect = container.getBoundingClientRect();
  const elementRect = element.getBoundingClientRect();

  if (containerRect.height === 0 || elementRect.height === 0) {
    return false;
  }

  return elementRect.top >= containerRect.top && elementRect.bottom <= containerRect.bottom;
}

function ensureChatVisibleInCompactGroup({
  chatId,
}: {
  chatId: ChatId,
}) {
  for (const item of sidebarItemsLocal.value) {
    switch (item.type) {
    case 'chat':
      continue;
    case 'chat_group': {
      const hiddenItemIndex = item.chatGroup.items.findIndex((chatItem, index) =>
        index >= COMPACT_THRESHOLD && chatItem.chat.id === chatId,
      );

      if (hiddenItemIndex === -1) continue;
      if (item.chatGroup.isCollapsed) return;
      if (expandedGroupIds.value.has(item.chatGroup.id)) return;

      expandedGroupIds.value.add(item.chatGroup.id);
      return;
    }
    default: {
      const _ex: never = item;
      return _ex;
    }
    }
  }
}

async function scheduleSidebarItemScroll({
  itemType,
  id,
  onlyWhenOutOfView,
}: {
  itemType: 'chat',
  id: ChatId | undefined,
  onlyWhenOutOfView: boolean,
} | {
  itemType: 'chat_group',
  id: ChatGroupId | undefined,
  onlyWhenOutOfView: boolean,
}) {
  if (!id || typeof document === 'undefined' || !navContainer.value) return;

  switch (itemType) {
  case 'chat':
    ensureChatVisibleInCompactGroup({ chatId: id });
    break;
  case 'chat_group':
    break;
  default: {
    const _ex: never = itemType;
    return _ex;
  }
  }

  return nextTick().then(() => new Promise<void>((resolve) => {
    window.setTimeout(() => {
      if (typeof document === 'undefined' || !navContainer.value) {
        resolve();
        return;
      }

      const selector = (() => {
        switch (itemType) {
        case 'chat':
          return `[data-sidebar-chat-id="${idToRaw({ id })}"]`;
        case 'chat_group':
          return `[data-sidebar-group-id="${idToRaw({ id })}"]`;
        default: {
          const _ex: never = itemType;
          return _ex;
        }
        }
      })();

      const el = navContainer.value.querySelector(selector);
      if (!(el instanceof HTMLElement)) {
        resolve();
        return;
      }
      if (onlyWhenOutOfView && isSidebarItemVisible({ container: navContainer.value, element: el })) {
        resolve();
        return;
      }

      scrollIntoViewSafe({
        container: navContainer.value,
        element: el,
        behavior: 'smooth',
        block: 'nearest',
      });
      resolve();
    }, 100);
  }));
}

watch(() => currentChat.value?.id, (id) => {
  void scheduleSidebarItemScroll({
    itemType: 'chat',
    id,
    onlyWhenOutOfView: true,
  });
}, { immediate: true });

watch(() => currentChatGroup.value?.id, (id) => {
  void scheduleSidebarItemScroll({
    itemType: 'chat_group',
    id,
    onlyWhenOutOfView: true,
  });
}, { immediate: true });

watch(activeFocusAreaVersion, () => {
  switch (activeFocusArea.value) {
  case 'chat':
    break;
  case 'sidebar':
  case 'chat-group-settings':
  case 'chat-settings':
  case 'settings':
  case 'onboarding':
  case 'dialog':
  case 'none':
  case 'search':
    return;
  default: {
    const _ex: never = activeFocusArea.value;
    return _ex;
  }
  }

  if (currentChat.value?.id) {
    void scheduleSidebarItemScroll({
      itemType: 'chat',
      id: currentChat.value.id,
      onlyWhenOutOfView: true,
    });
    return;
  }

  void scheduleSidebarItemScroll({
    itemType: 'chat_group',
    id: currentChatGroup.value?.id,
    onlyWhenOutOfView: true,
  });
});

function isGroupCompactExpanded({ groupId }: { groupId: ChatGroupId }) {
  return expandedGroupIds.value.has(groupId);
}

function toggleGroupCompactExpansion({ groupId }: { groupId: ChatGroupId }) {
  if (expandedGroupIds.value.has(groupId)) {
    collapsingGroupIds.value.add(groupId);
    expandedGroupIds.value.delete(groupId);
    // Wait for the transition to finish (400ms) before removing items from DOM
    setTimeout(() => {
      collapsingGroupIds.value.delete(groupId);
    }, 400);
  } else {
    expandedGroupIds.value.add(groupId);
  }
}

// Custom directive for auto-focusing elements
const vFocus: ObjectDirective<HTMLElement> = {
  mounted: (el) => el.focus(),
};

const isMac = typeof window !== 'undefined' && /Mac|iPod|iPhone|iPad/.test(navigator.platform);
const newChatShortcutText = isMac ? '⌘⇧O' : 'Ctrl+Shift+O';

function handleClickOutside({ event }: { event: MouseEvent }) {
  const target = event.target as HTMLElement;
  if (activeActionGroupId.value && !target.closest('.group-action-container')) {
    activeActionGroupId.value = null;
  }
}

useEventTargetListener(document, 'mousedown', (event) => handleClickOutside({ event }));

onMounted(() => {
  syncLocalItems();
  if (currentChat.value?.id) {
    void scheduleSidebarItemScroll({
      itemType: 'chat',
      id: currentChat.value.id,
      onlyWhenOutOfView: true,
    });
    return;
  }

  void scheduleSidebarItemScroll({
    itemType: 'chat_group',
    id: currentChatGroup.value?.id,
    onlyWhenOutOfView: true,
  });
});

function captureSidebarItemRects() {
  const rects = new Map<string, DOMRect>();
  if (!navContainer.value) return rects;

  navContainer.value.querySelectorAll<HTMLElement>('[data-sidebar-chat-id]').forEach(element => {
    const id = element.dataset.sidebarChatId;
    if (!id) return;
    rects.set(`chat:${id}`, element.getBoundingClientRect());
  });

  navContainer.value.querySelectorAll<HTMLElement>('[data-sidebar-group-id]').forEach(element => {
    const id = element.dataset.sidebarGroupId;
    if (!id) return;
    rects.set(`group:${id}`, element.getBoundingClientRect());
  });

  return rects;
}

function animateSidebarItemMoves({ previousRects }: { previousRects: Map<string, DOMRect> }) {
  if (previousRects.size === 0 || typeof window === 'undefined') return;
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;

  void nextTick(() => {
    if (!navContainer.value || isDragging.value) return;

    const applyMove = ({ key, element }: { key: string, element: HTMLElement }) => {
      const previous = previousRects.get(key);
      if (!previous) return;

      const current = element.getBoundingClientRect();
      const deltaY = previous.top - current.top;
      const deltaX = previous.left - current.left;
      if (Math.abs(deltaY) < 1 && Math.abs(deltaX) < 1) return;

      element.classList.add('sidebar-reorder-animating');
      element.style.transform = `translate(${deltaX}px, ${deltaY}px)`;
      element.style.transition = 'transform 0ms';

      const runNextFrame: typeof window.requestAnimationFrame = window.requestAnimationFrame ?? ((callback) => window.setTimeout(callback, 16));
      runNextFrame(() => {
        element.style.transition = 'transform 180ms cubic-bezier(0.22, 1, 0.36, 1)';
        element.style.transform = '';
      });

      window.setTimeout(() => {
        element.classList.remove('sidebar-reorder-animating');
        element.style.transition = '';
        element.style.transform = '';
      }, 220);
    };

    navContainer.value.querySelectorAll<HTMLElement>('[data-sidebar-chat-id]').forEach(element => {
      const id = element.dataset.sidebarChatId;
      if (!id) return;
      applyMove({ key: `chat:${id}`, element });
    });

    navContainer.value.querySelectorAll<HTMLElement>('[data-sidebar-group-id]').forEach(element => {
      const id = element.dataset.sidebarGroupId;
      if (!id) return;
      applyMove({ key: `group:${id}`, element });
    });
  });
}

function syncLocalItems() {
  if (isDragging.value || isInternalUpdate) return;
  const previousRects = captureSidebarItemRects();
  // Use JSON.parse/stringify for robust deep cloning of reactive objects in test environments
  sidebarItemsLocal.value = JSON.parse(JSON.stringify(sidebarItems.value));
  animateSidebarItemMoves({ previousRects });
}

// Watch for external sidebar changes (new chats, deletions, reordering) to sync local list
watch(() => sidebarItems.value, () => {
  syncLocalItems();
}, { deep: true });

// --- DND Handlers ---

function onDragStart() {
  isDragging.value = true;
}

async function onDragEnd() {
  isInternalUpdate = true;
  dragHoverGroup.value = null;
  if (dragHoverTimeout) {
    clearTimeout(dragHoverTimeout);
    dragHoverTimeout = null;
  }
  // Sync the UI structure to storage
  await persistSidebarStructure({ topLevelItems: sidebarItemsLocal.value });

  // Wait for DOM and Sortable cleanup
  await nextTick();
  isDragging.value = false;
  setTimeout(() => {
    isInternalUpdate = false;
  }, 100);
}

function onDragOverGroup({ groupId }: { groupId: ChatGroupId }) {
  if (!isDragging.value) return;
  if (dragHoverGroup.value === groupId) return;

  dragHoverGroup.value = groupId;
  if (dragHoverTimeout) clearTimeout(dragHoverTimeout);

  dragHoverTimeout = setTimeout(() => {
    const group = chatGroups.value.find(g => g.id === groupId);
    if (group && group.isCollapsed) {
      setChatGroupCollapsed({ groupId, isCollapsed: false });
    }
  }, 600); // 600ms hover to expand
}

function onDragLeaveGroup() {
  dragHoverGroup.value = null;
  if (dragHoverTimeout) {
    clearTimeout(dragHoverTimeout);
    dragHoverTimeout = null;
  }
}

/**
 * Move callback to prevent invalid nesting.
 * Only chats can be moved into chat groups. Chat groups cannot be nested.
 */
function checkMove({ evt }: { evt: { draggedContext: { element: SidebarItem }, to: HTMLElement } }) {
  const draggedItem = evt.draggedContext.element;
  // If dragging into a nested list (a chat group's items)
  if (evt.to.classList.contains('nested-draggable')) {
    // Only allow chats
    switch (draggedItem.type) {
    case 'chat':
      return true;
    case 'chat_group':
      return false;
    default: {
      const _ex: never = draggedItem;
      return _ex;
    }
    }
  }
  return true;
}

// --- Actions ---

async function handleCreateChatGroup() {
  const name = newChatGroupName.value.trim();
  if (!name) {
    isCreatingChatGroup.value = false;
    return;
  }
  skipLeaveAnimation.value = true;
  await createChatGroup({ name });
  newChatGroupName.value = '';
  isCreatingChatGroup.value = false;
  // Reset flag after transition would have finished
  setTimeout(() => {
    skipLeaveAnimation.value = false;
  }, 200);
}

function handleCreateChatGroupBlur() {
  if (!newChatGroupName.value.trim()) {
    skipLeaveAnimation.value = false;
    isCreatingChatGroup.value = false;
  }
}

function cancelCreateChatGroup() {
  skipLeaveAnimation.value = false;
  isCreatingChatGroup.value = false;
  newChatGroupName.value = '';
}

async function handleDeleteChatGroup({ group }: { group: ChatGroup }) {
  const hasItems = group.items && group.items.length > 0;
  const hasCustomSettings = !!(group.systemPrompt || group.modelId || group.endpoint || group.lmParameters);

  if (hasItems || hasCustomSettings) {
    const confirmed = await showConfirm({
      title: await ensureStrings.Sidebar__delete_group_question(),
      message: await ensureStrings.Sidebar__delete_group_warning({ groupName: group.name, chatCount: group.items.length }),
      confirmButtonText: await ensureStrings.Sidebar__delete_group(),
      cancelButtonText: await ensureStrings.Sidebar__cancel(),
      confirmButtonVariant: 'danger',
    });
    if (!confirmed) return;
  }

  await deleteChatGroup({ id: group.id });
}

async function handleNewChat({ groupId }: { groupId: ChatGroupId | undefined }) {
  documentMetadata?.finishHomeIntroduction();
  setActiveFocusArea({ area: 'chat' });
  await createNewChat({
    groupId,
    modelId: undefined,
    systemPrompt: undefined,
  });
  if (currentChat.value) {
    router.push(`/chat/${idToRaw({ id: currentChat.value.id })}`);
  }
}

async function handleOpenChat({ id }: { id: ChatId }) {
  documentMetadata?.finishHomeIntroduction();
  await openChat({ id });
  router.push(`/chat/${idToRaw({ id })}`);
}

async function handleOpenChatGroup({ id }: { id: ChatGroupId }) {
  openChatGroup({ id });
  router.push(`/chat-group/${idToRaw({ id })}`);
}

// Clear lastNavigatedId when store catches up to prevent stale index calculations
watch([() => currentChat.value?.id, () => currentChatGroup.value?.id], ([chatId, groupId]) => {
  if ((chatId && idToRaw({ id: chatId }) === lastNavigatedId.value) || (groupId && idToRaw({ id: groupId }) === lastNavigatedId.value)) {
    lastNavigatedId.value = null;
  }
});

async function handleDeleteChat({ id, groupId }: { id: ChatId, groupId: ChatGroupId | undefined }) {
  const isCurrent = currentChat.value?.id === id;
  const redirectAfterDelete = groupId
    ? `/chat-group/${idToRaw({ id: groupId })}`
    : '/';
  await deleteChat({ id });
  if (isCurrent) await router.push(redirectAfterDelete);
}

function startEditing({ id, title }: { id: ChatId, title: string | null }) {
  editingId.value = id;
  editingTitle.value = title || '';
}

async function saveRename() {
  if (editingId.value && editingTitle.value.trim()) {
    await renameChat({ id: editingId.value, newTitle: editingTitle.value.trim() });
  }
  editingId.value = null;
}

function startEditingChatGroup({ chatGroup }: { chatGroup: ChatGroup }) {
  editingChatGroupId.value = chatGroup.id;
  editingChatGroupName.value = chatGroup.name;
}

async function saveChatGroupRename() {
  if (editingChatGroupId.value && editingChatGroupName.value.trim()) {
    await renameChatGroup({ groupId: editingChatGroupId.value, newName: editingChatGroupName.value.trim() });
  }
  editingChatGroupId.value = null;
}

async function handleGlobalModelChange({ newModelId }: { newModelId: string | undefined }) {
  if (!newModelId) return;
  await updateGlobalModel({ modelId: newModelId });
}

function getGroupItems({ groupId }: { groupId: ChatGroupId }) {
  const group = sidebarItemsLocal.value.find(item => item.type === 'chat_group' && item.chatGroup.id === groupId);
  if (!group || group.type !== 'chat_group') return [];

  const items = group.chatGroup.items;
  if (isGroupCompactExpanded({ groupId }) || collapsingGroupIds.value.has(groupId) || items.length <= COMPACT_THRESHOLD) {
    return items;
  }
  return items.slice(0, COMPACT_THRESHOLD);
}

function updateGroupItems({ groupId, newItems }: { groupId: ChatGroupId, newItems: ChatSidebarItem[] }) {
  const groupIndex = sidebarItemsLocal.value.findIndex(item => item.type === 'chat_group' && item.chatGroup.id === groupId);
  if (groupIndex === -1) return;

  const group = sidebarItemsLocal.value[groupIndex];
  if (!group || group.type !== 'chat_group') return;

  const fullList = group.chatGroup.items;
  if (isGroupCompactExpanded({ groupId }) || collapsingGroupIds.value.has(groupId) || fullList.length <= COMPACT_THRESHOLD) {
    group.chatGroup.items = newItems;
  } else {
    const hiddenItems = fullList.slice(COMPACT_THRESHOLD);
    group.chatGroup.items = [...newItems, ...hiddenItems];
  }
}

function useGroupItemsModel({ groupId }: { groupId: ChatGroupId }) {
  return computed({
    get: () => getGroupItems({ groupId }),
    set: (val) => updateGroupItems({ groupId, newItems: val }),
  });
}

function handleToggleChatGroupCollapse({ chatGroup }: { chatGroup: ChatGroup }) {
  // Toggle locally for instant, flicker-free feedback
  chatGroup.isCollapsed = !chatGroup.isCollapsed;

  // Reset compact expansion state if collapsed
  if (chatGroup.isCollapsed) {
    expandedGroupIds.value.delete(chatGroup.id);
  }

  // Persist to store
  setChatGroupCollapsed({
    groupId: chatGroup.id,
    isCollapsed: chatGroup.isCollapsed,
  });
}

onKeyStroke(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'], (e) => {
  const area = activeFocusArea.value;
  switch (area) {
  case 'sidebar':
    break;
  case 'chat':
  case 'chat-group-settings':
  case 'chat-settings':
  case 'settings':
  case 'onboarding':
  case 'dialog':
  case 'none':
  case 'search':
    return;
  default: {
    const _ex: never = area;
    throw new Error(`Unhandled focus area: ${_ex}`);
  }
  }

  if (
    editingId.value ||
    editingChatGroupId.value ||
    isCreatingChatGroup.value
  ) {
    return;
  }

  if (visibleItems.value.length === 0) return;

  // Prioritize the ID we just navigated to, then group, then chat.
  // This prevents jumping back if the store hasn't updated currentChat yet.
  const currentId = focusedId.value;

  let currentIndex = currentId ? visibleItems.value.findIndex(i => i.id === currentId) : -1;

  // Fallback: If current item is hidden (e.g. inside collapsed group),
  // try using its parent group's index as starting point.
  if (currentIndex === -1 && currentChat.value?.groupId) {
    currentIndex = visibleItems.value.findIndex(i => i.id === currentChat.value?.groupId);
  }

  if (e.key === 'ArrowDown') {
    const nextIndex = currentIndex + 1;
    if (nextIndex < visibleItems.value.length) {
      e.preventDefault();
      const item = visibleItems.value[nextIndex];
      if (item) {
        switch (item.type) {
        case 'expand_button':
          lastNavigatedId.value = item.id;
          break;
        case 'chat':
        case 'chat_group':
          lastNavigatedId.value = idToRaw({ id: item.id });
          break;
        default: {
