          break;
        case 'chat_group':
          handleOpenChatGroup({ id: item.id });
          break;
        case 'expand_button':
          break;
        default: {
          const _ex: never = type;
          throw new Error(`Unhandled item type: ${_ex}`);
        }
        }
      }
    }
  } else if (e.key === 'ArrowUp') {
    const nextIndex = currentIndex - 1;
    if (nextIndex >= 0) {
      e.preventDefault();
      const item = visibleItems.value[nextIndex];
      if (item) {
        switch (item.type) {
        case 'expand_button':
          lastNavigatedId.value = item.id;
          break;
        case 'chat':
        case 'chat_group':
          lastNavigatedId.value = idToRaw({ id: item.id });
          break;
        default: {
          const _ex: never = item;
          throw new Error(`Unhandled item type: ${((_ex satisfies never) as { readonly type: string }).type}`);
        }
        }
        const type = item.type;
        switch (type) {
        case 'chat':
          handleOpenChat({ id: item.id });
          break;
        case 'chat_group':
          handleOpenChatGroup({ id: item.id });
          break;
        case 'expand_button':
          break;
        default: {
          const _ex: never = type;
          throw new Error(`Unhandled item type: ${_ex}`);
        }
        }
      }
    }
