      if (group) {
        if (e.key === 'ArrowRight' && group.isCollapsed) {
          e.preventDefault();
          handleToggleChatGroupCollapse({ chatGroup: group });
        } else if (e.key === 'ArrowLeft' && !group.isCollapsed) {
          e.preventDefault();
          handleToggleChatGroupCollapse({ chatGroup: group });
        }
      }
